# ---- every number the video says, asserted (CHECKS) -------------------------------------------------------------------------
x() { $G -qE -- "$2" ".r-$1.out" || die "$1: expected /$2/"; }
blk() { awk -v a="$2" -v b="$3" 'index($0, a) == 1 { f = 1; next } b != "" && index($0, b) == 1 { f = 0 } f' ".r-$1.out"; }
has() { printf '%s\n' "$1" | $G -qxF -- "$2" || die "$3: expected the line: $2"; }
nhas() { ! printf '%s\n' "$1" | $G -qF -- "$2" || die "$3: did not expect: $2"; }
cnt() { printf '%s\n' "$1" | $G -cxF -- "$2" || true; }
# hygiene: every raw capture run and every file this unit holds - 0 raw tokens, 0 raw passwords
for f in .harness/raw-*; do [ "$(paste -sd' ' "$f")" = "0 0" ] || die "a capture's raw output held the token or the password ($f: $(paste -sd' ' "$f"))"; done
[ "$(find . -type f ! -path './.m2-demo/*' -print0 | xargs -0 cat 2> /dev/null | LC_ALL=C $G -aoF -- "$PGPW" | wc -l | tr -d ' ')" = 1 ] || die "the password is held raw somewhere but its own file, .harness/pg/password"
[ "$(raw "$PGPW" "$PF")" = 1 ] || die "the password's file does not hold it"
for f in .r-*.out README.md exercise/README.md exercise/SOLUTION.md receipts.md5 harness/src/probe/map/*.java .harness/*.log; do [ "$(raw "$TOKEN" "$f")" = 0 ] || die "$f holds the demo token, raw"; done
[ "$LOGS" -gt 0 ] || die "a token count never ran"
[ "$GENW" = 0 ] || die "a schema step failed in a log: 'GenerationTarget encountered exception' $GENW times (R.213)"
for f in .r-*.out; do
  ! $G -qE '/Users/|/private/|/home/|/var/folders/' "$f" || die "$f holds an absolute path"
  # a line quoted from the anchor's own files (grep -rn's "FILE:LINE:" lines, a diff's -/+ lines) may name the unit that wrote it
  ! $G -vE '^(  (README\.md|tiffinbox-core/[^ :]+):[0-9]+:|    [-+])' "$f" | $G -qE 'c[0-9]-unit[0-9]|unit ?[0-9]' || die "$f holds a unit number"
  ! $G -qE ' (with PID|started by) |surefirebooter|Time elapsed|time="| in [0-9.]+ seconds' "$f" || die "$f holds Boot's process line, a Surefire booter path, a time or Boot's seconds"
  ! $G -qE '^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T|"timestamp":"?[0-9]|(exec|handler|task)-[0-9]' "$f" || die "$f holds a log time, a timestamp or a thread number"
  ! $G -qE 'using Java [0-9]|Darwin|arm64|aarch64|musl' "$f" || die "$f holds an OS or a JDK version token (R.151)"
  ! $G -qE 'jdbc:h2:mem:[0-9a-f]{8}-' "$f" || die "$f holds a generated database name, unmasked"
  ! $G -qE '(127\.0\.0\.1:|port )(49|5[0-9]|6[0-5])[0-9][0-9][0-9]([^0-9]|$)' "$f" || die "$f holds a random port (R.147)"
  ! $G -qE '[0-9]+\.[0-9]+ ms' "$f" || die "$f holds a millisecond figure, unmasked (R.207)"
  ! $G -qE '^ +at [a-z]' "$f" || die "$f holds a stack frame"; done
for f in .r-*.out; do ! $G -E '^ *\$ ' "$f" | $G -oE 'https?://[^ '"'"']+' | $G -vE '^http://127\.0\.0\.1:' > /dev/null || die "$f runs a command with a URL that is not 127.0.0.1's"; done
for f in .r-*.out; do ! $G -E '^ *\$ \(?(cd [^ ]+ && )?(exec )?java ' "$f" | $G -vF -- "java $JL " > /dev/null || die "$f starts a JVM without its locale pinned (S6.1)"; done
for f in .r-*.out; do a=$($G -cE '^\$ cd \.harness/(before|after) && java ' "$f" || true); b=$($G -cxF "  secrets/ before the start: tiffinbox/shutdown-token - the token's file, and nothing else" "$f" || true)
  [ "$a" = "$b" ] || die "$f: $a starts, $b secrets/ listings (R.158)"; done
K1='pki''ll'; K2='kill''all'; for f in receipts.sh harness/shutdown.sh; do ! $G -v '^ *#' "$f" | $G -qwE "$K1|$K2" || die "$f names $K1 or $K2 - every process is stopped by its pid"; done
for f in receipts.sh exercise/README.md exercise/SOLUTION.md; do ! $G -nE '(^|[;&|({] *)wait *($|[;&|)}])' "$f" | $G -vE '^[0-9]+: *#' > /dev/null || die "$f has a bare wait (S6.9)"; done
for f in receipts.sh README.md exercise/README.md exercise/SOLUTION.md; do ! $G -nE '^[A-Za-z_][A-Za-z_0-9]*="?--[^ "]+ +--' "$f" > /dev/null || die "$f holds a one-string multi-option variable (R.193)"; done
! $G -rq 'probe\.map' after/tiffinbox-web after/tiffinbox-core || die "after/'s code names the course's harness - it is never TiffinBox's"
! $G -rqE '^package com\.tiffinbox' harness/src || die "a harness class sits in com.tiffinbox (R.43)"
# R.213: SQL keywords are never a name here (the harness's tables and columns)
! $G -rqiwE '(class|String|Long|UUID) +(order|offset|user|value|key)\b' harness/src || die "a harness entity or field is named after an SQL keyword (R.213)"
[ -z "$(find . "$UP" -maxdepth 1 \( -name '*.mv.db' -o -name '*.trace.db' \) 2> /dev/null; find . -path ./.m2-demo -prune -o \( -name '*.mv.db' -o -name '*.trace.db' \) -print)" ] || die "an H2 database file exists - every H2 here is in memory"
echo "  hygiene: 0 raw tokens and 0 raw passwords in $(ls .harness/raw-* | wc -l | tr -d ' ') raw capture runs, $(ls .r-*.out | wc -l | tr -d ' ') captures and every log ($LOGS JVM logs; the password only in its own file); 'GenerationTarget encountered exception' 0; no path, unit number, time, millisecond figure, OS token, random port or stack frame in any capture; every JVM pinned; every start's secrets/ listed; no kill by name; no bare wait; options as arrays; no H2 file"

# "the version sweep: 4.1.2 is the newest 4.1, 4.1.3 absent, 4.2 not GA" (R.223)
SW=$(cat .r-sweep.out)
for l in "  $SWMD5" '  dated: 2026-11-04' '  4.1.x GA (no -M, no -RC): 4.1.0 4.1.1 4.1.2 · the newest: 4.1.2 · 4.1.3: absent' "  the anchor's parent (after/pom.xml): 4.1.2 · Hibernate in after/'s jar: hibernate-core-7.4.13.Final.jar"; do has "$SW" "$l" "sweep"; done
printf '%s\n' "$SW" | $G -qE '^  4\.2\.x versions: .* · a 4\.2\.x GA: none$' || die "sweep: a 4.2.x GA appeared - the brief's rule: name it, never adopt it mid-course"
echo "  sweep: the dated file $SWMD5 - newest 4.1.x GA 4.1.2, 4.1.3 absent, no 4.2.x GA; the anchor on 4.1.2, Hibernate 7.4.13.Final"

# "IDENTITY: the INSERT between before and after persist; SEQUENCE: the sequence at persist, the INSERT after before commit - both databases; id 5 on the anchor's own table"
for d in H2 PostgreSQL; do
  WA=$(blk when "on $d - A," "on $d - B,"); WB=$(blk when "on $d - B," "on $d - A'"); WA2=$(blk when "on $d - A'" "on $d - C"); WC=$(blk when "on $d - C" "on ")
  [ "$d" = H2 ] && { IA='  DEBUG org.hibernate.SQL : insert into identity_customer (name,id) values (?,default)'; IC='  DEBUG org.hibernate.SQL : insert into customer (meal_type,meals_per_day,name,price_per_meal,id) values (?,?,?,?,default)'; SQ='  DEBUG org.hibernate.SQL : select next value for sequence_customer_seq'; DBL='  PROBE database: H2 2.5.250'; } \
    || { IA='  DEBUG org.hibernate.SQL : insert into identity_customer (name) values (?)'; IC='  DEBUG org.hibernate.SQL : insert into customer (meal_type,meals_per_day,name,price_per_meal) values (?,?,?,?)'; SQ="  DEBUG org.hibernate.SQL : select nextval('sequence_customer_seq')"; DBL='  PROBE database: PostgreSQL 18.6'; }
  for b in "$WA" "$WA2"; do for l in "$IA" '  PROBE before persist(): id null' '  PROBE after persist(): id 1' '  PROBE statistics: statements prepared 1 | inserts 1 | updates 0 | deletes 0 | flushes 1' '  PROBE jdbc: prepareStatement 1 | executeUpdate 1 | addBatch 0 | executeBatch 0 | executeQuery 0 | execute 0' "  the INSERT's place, from the log's order: between before persist() and after persist()" '  exit 0 · '"'"'GenerationTarget encountered exception'"'"': 0'; do has "$b" "$l" "when $d A/A'"; done
    printf '%s\n' "$b" | $G -q "^$DBL" || die "when $d A: its database: line"; done
  [ "$(printf '%s\n' "$WA" | $G -v '^\$ ')" = "$(printf '%s\n' "$WA2" | $G -v '^\$ ')" ] || die "when $d: A' = A, line for line"
  for l in "$SQ" '  DEBUG org.hibernate.SQL : insert into sequence_customer (name,id) values (?,?)' '  PROBE after persist(): id 1' '  PROBE statistics: statements prepared 2 | inserts 1 | updates 0 | deletes 0 | flushes 1' \
      "  the INSERT's place, from the log's order: between before commit and after commit · the sequence call's place: between before persist() and after persist()"; do has "$WB" "$l" "when $d B"; done
  for l in "$IC" '  PROBE seeded by the shipped Database (createAndSeed), read by a second connection: [1 | Ravi, 2 | Meera, 3 | Sunil, 4 | Priya]' '  PROBE before persist(): id null' '  PROBE after persist(): id 5' \
      '  PROBE statistics: statements prepared 1 | inserts 1 | updates 0 | deletes 0 | flushes 1' '  PROBE second connection: [1 | Ravi, 2 | Meera, 3 | Sunil, 4 | Priya, 5 | Kavya]' "  the INSERT's place, from the log's order: between before persist() and after persist()"; do has "$WC" "$l" "when $d C"; done
  printf '%s\n' "$WC" | $G -q "^$DBL" || die "when $d C: its database: line"; done
[ "$($G -cxF '  PROBE Hibernate ORM core version (org.hibernate.Version.getVersionString()): 7.4.13.Final' .r-when.out)" = 8 ] || die "when: the version line in each of the eight runs (R.222)"
echo "  when: H2 and PostgreSQL - A/A' IDENTITY: the INSERT between before persist() and after persist() (H2 values (?,default), PG no id column), id 1, statements 1; B SEQUENCE: the sequence call at persist, the INSERT after before commit, statements 2; C the anchor's table seeded 1-4 by the shipped Database, then id 5 (statements 1), a second connection reads 5 | Kavya"

# "the names: <entity>_seq by 50, your own name, allocationSize 1 by 1, legacy hibernate_sequence; AUTO is a sequence; the same text on both"
for s in std legacy; do has "$(cat .r-seqnames.out)" "  the H2 script against the Postgres script ($s): the same, byte for byte: yes" "seqnames $s: H2 = PG"; done
SN=$(blk seqnames "on H2 - Hibernate's default" "on PostgreSQL - Hibernate's default"); SL=$(blk seqnames "on H2 - hibernate.id" "on PostgreSQL - hibernate.id")
for l in '    create sequence sequence_customer_seq start with 1 increment by 50;' '    create sequence auto_customer_seq start with 1 increment by 50;' '    create sequence customer_seq start with 1 increment by 50;' '    create sequence one_seq start with 1 increment by 1;' \
    '    create table identity_customer (id bigint generated by default as identity, name varchar(255), primary key (id));' '  PROBE AutoCustomer generator: org.hibernate.id.enhanced.SequenceStyleGenerator' '  PROBE IdentityCustomer generator: org.hibernate.id.IdentityGenerator' '  PROBE UuidCustomer generator: org.hibernate.id.uuid.UuidGenerator'; do has "$SN" "$l" "seqnames default"; done
has "$SL" '    create sequence hibernate_sequence start with 1 increment by 1;' "seqnames legacy"; nhas "$SL" 'auto_customer_seq' "seqnames legacy: no auto_customer_seq"; nhas "$SN" 'hibernate_sequence' "seqnames default: no hibernate_sequence"
echo "  seqnames: <entity>_seq increment by 50 (SEQUENCE and AUTO, both SequenceStyleGenerator), customer_seq by name, one_seq increment by 1, hibernate_sequence only under legacy; the H2 and Postgres scripts byte for byte"

# "two hundred statements prepared, or six - and the insert sent in four batches; the SQL log prints two hundred inserts both times"
bline() { printf '%s\n' "$1" | awk -v k="$2" 'index($0, k) == 1 { f = 1; next } f && /^  [a-z]/ { exit } f'; }
for d in H2 PostgreSQL; do BB=$(blk batch "on $d -" "on "); BB=${BB:-$(blk batch "on $d -" "")}
  # mapping | SQL insert lines | sequence calls | statements | executeUpdate addBatch executeBatch | batch-log lines
  for row in 'ids.IdentityCustomer (hibernate.jdbc.batch_size 50):0:200:200:0:0:0:no' 'ids.SequenceCustomer (hibernate.jdbc.batch_size 50):5:6:0:200:4:4:yes' \
      'ids.OneSeqCustomer (hibernate.jdbc.batch_size 50):200:201:0:200:4:4:yes' 'ids.UuidCustomer (hibernate.jdbc.batch_size 50):0:1:0:200:4:4:yes' 'ids.SequenceCustomer (no hibernate.jdbc.batch_size):5:205:200:0:0:0:no'; do
    IFS=':' read -r k sq stn eu ab ebn bl eb <<< "$row"
    b=$(bline "$BB" "  $k: 200 persists")
    [ -n "$b" ] || die "batch $d: no block for $k"
    printf '%s\n' "$b" | $G -qxF "    the SQL log: insert lines 200 · sequence calls $sq · the batch logger: Executing JDBC batch lines $bl · the INFO HHH100501 line $( [ "${k#*no hibernate}" = "$k" ] && echo 1 || echo 0)" || die "batch $d $k: the SQL log's counts"
    printf '%s\n' "$b" | $G -qE "^    statistics: statements prepared $stn \| inserts 200 \|" || die "batch $d $k: statements prepared $stn"
    printf '%s\n' "$b" | $G -qE "^    jdbc: prepareStatement $stn \| executeUpdate $eu \| addBatch $ab \| executeBatch $ebn \| executeQuery $sq \| execute 0$" || die "batch $d $k: the driver's calls"
    printf '%s\n' "$b" | $G -qxF "    batched, by the check that counts the SQL log's insert lines (200 of 200): yes · by executeBatch > 0 (the driver's calls): $eb" || die "batch $d $k: the two checks"
    printf '%s\n' "$b" | $G -qxF '    rows, read by a second connection: [200]' || die "batch $d $k: 200 rows"; done; done
echo "  batch: H2 and PostgreSQL alike - IDENTITY statements prepared 200, executeBatch 0; SEQUENCE 6 (5 sequence calls + 1 INSERT), executeBatch 4; allocationSize 1: 201, 200 sequence calls, executeBatch 4; UUID 1, executeBatch 4; no batch_size: 205, executeBatch 0; the SQL log 200 insert lines and HHH100501 in every batched run - the line-count check says 'batched' for IDENTITY, executeBatch > 0 says no (R.206)"

# "more than twice as slow on H2, more than five times on Postgres - on this Mac": the threshold lines, three JVMs each (R.207)
TM=$(cat .r-time.out)
for d in H2:2 PostgreSQL:5; do for j in 1 2 3; do [ "$(cnt "$TM" "  exit 0 · on ${d%%:*}, JVM $j: ratio >= ${d#*:}: true")" = 1 ] || die "time: ${d%%:*} JVM $j - ratio >= ${d#*:} not true"; done; done
[ "$(cnt "$TM" '  PROBE design: rows per run 1000 | warm-up rounds 10 | timed rounds 9 | IDENTITY and SEQUENCE alternate which runs first | hibernate.jdbc.batch_size 50 | one transaction per run')" = 6 ] || die "time: the fixed design in all six JVMs"
[ "$(cnt "$TM" '  PROBE IdentityCustomer per-run times, the timed rounds (ms): [9 values, masked]')" = 6 ] && [ "$(cnt "$TM" '  PROBE SequenceCustomer per-run times, the timed rounds (ms): [9 values, masked]')" = 6 ] || die "time: 9 timed runs per mapping per JVM"
[ "$($G -c ' ratio IDENTITY/SEQUENCE [0-9.]*$' .r-time.medians)" = 6 ] || die "time: the run of record's six ratios"
RH=$(sed -n 's/^H2 JVM [123]: .*ratio IDENTITY\/SEQUENCE //p' .r-time.medians | paste -sd'/' -); RP=$(sed -n 's/^PostgreSQL JVM [123]: .*ratio IDENTITY\/SEQUENCE //p' .r-time.medians | paste -sd'/' -)
echo "  time: W 10, R 9, N 1000, 3 JVMs per database - H2 ratio >= 2: true ×3, PostgreSQL ratio >= 5: true ×3 (the run of record's ratios, .r-time.medians, terminal only: H2 $RH, PostgreSQL $RP)"

# "TiffinBox on Postgres: A refused at AUTO_INCREMENT, B ready and Kavya 5 by the JDBC repository, C the restart keeps the four, A' = A"
PG=$(cat .r-pgstart.out); PA=$(blk pgstart "A - before/" "B - after/"); PB=$(blk pgstart "B - after/" "C (labelled"); PC=$(blk pgstart "C (labelled" "A' - A again"); PA2=$(blk pgstart "A' - A again" "")
for l in '  tiffinbox-core/src/main/java/com/tiffinbox/CustomerEntity.java' '  tiffinbox-core/src/main/java/com/tiffinbox/Database.java' '  README.md' \
    '    -                    id            BIGINT AUTO_INCREMENT PRIMARY KEY,' '    +                    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,' '    -                    id          BIGINT AUTO_INCREMENT PRIMARY KEY,' '    +                    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,' \
    '  5432/tcp -> 127.0.0.1:19858'; do has "$PG" "$l" "pgstart: the change and the container"; done
[ "$(printf '%s\n' "$PG" | sed -n '/^the change - after/,/^Database.java:/p' | $G -c '^  ')" = 3 ] || die "pgstart: the change touches three files"
# every AUTO_INCREMENT left in after/ is history, each named: Database's comment (2 lines), the anchor README's unit 03 note and Course 5's note
AI=$(printf '%s\n' "$PG" | sed -n '/^every line of after\/ that still names AUTO_INCREMENT/,/^the container/p' | $G '^  ' | sed -E 's/^  ([^:]+):([0-9]+):.*/\1:\2/' | paste -sd' ' -)
case "$AI" in "tiffinbox-core/src/main/java/com/tiffinbox/Database.java:27 tiffinbox-core/src/main/java/com/tiffinbox/Database.java:28 README.md:"*) ;; *) die "pgstart: AUTO_INCREMENT in after/'s code beyond Database's comment: $AI" ;; esac
NAI=$(printf '%s\n' "$PG" | sed -n '/^every line of after\/ that still names AUTO_INCREMENT/,/^the container/p' | $G -c '^  README\.md:' || true)
[ "$(printf '%s\n' "$PG" | sed -n '/^every line of after\/ that still names AUTO_INCREMENT/,/^the container/p' | $G '^  README\.md:' | $G -cE 'unit 06|GENERATED BY DEFAULT|syntax error at or near "AUTO_INCREMENT"' || true)" = "$NAI" ] || die "pgstart: a README line names AUTO_INCREMENT without its history (unit 06, the new DDL, or Course 5's error)"
for b in "$PA" "$PA2"; do for l in '    ERROR o.s.boot.SpringApplication: Application run failed' "      Caused by: org.springframework.beans.factory.BeanCreationException: Error creating bean with name 'database': Invocation of init method failed" \
    '      Caused by: org.postgresql.util.PSQLException: ERROR: syntax error at or near "AUTO_INCREMENT"' '    INFO org.hibernate.orm.core: HHH000001: Hibernate ORM core version 7.4.13.Final' '      Database version: 18.6'; do has "$b" "$l" "pgstart A/A': the trio"; done
  printf '%s\n' "$b" | $G -qE '^  exit 1 · it listened on: nothing · listening on 1985[05] now: 0$' || die "pgstart A/A': exit 1, never listened"; done
[ "$(printf '%s\n' "$PA" | $G -v '^\$ ' | sed 's/ a1 / aN /; s#/a1?#/aN?#; s/1985[05]/1985x/g')" = "$(printf '%s\n' "$PA2" | $G -v '^\$ ' | sed 's/ a2 / aN /; s#/a2?#/aN?#; s/1985[05]/1985x/g')" ] || die "pgstart: A' = A, line for line (its database's name and port aside)"
for l in '  listens on: 127.0.0.1:19851 · loopback only: yes' '  {"name":"Kavya","mealsPerDay":2,"pricePerMeal":110,"mealType":"VEG"} 201' '  1|Ravi 2|Meera 3|Sunil 4|Priya 5|Kavya' '    INFO com.tiffinbox.web.TiffinBoxServer: Started TiffinBoxServer' \
    "  its log's lines - org.hibernate.SQL: 0 · of them 'insert into': 0 · WARN: 0 · ERROR: 0 · 'GenerationTarget encountered exception': 0" '      Database JDBC URL [jdbc:postgresql://127.0.0.1:19858/b1?user=sa&password=[masked: the 24-character password]]' \
    '    INFO com.zaxxer.hikari.pool.HikariPool: HikariPool-1 - Added connection org.postgresql.jdbc.PgConnection@…'; do has "$PB" "$l" "pgstart B: ready on Postgres, Kavya 5 by the JDBC repository"; done
for l in '  listens on: 127.0.0.1:19852 · loopback only: yes' '  1|Ravi 2|Meera 3|Sunil 4|Priya'; do has "$PC" "$l" "pgstart C: the restart"; done
nhas "$PC" 'Kavya' "pgstart C: no Kavya"; nhas "$PC" '/customers --data' "pgstart C: no POST"; nhas "$PC" '"name":"Kavya"' "pgstart C: no POST"
[ "$(printf '%s\n' "$PC" | $G -n '1|Ravi 2|Meera 3|Sunil 4|Priya$' | cut -d: -f1)" -lt "$(printf '%s\n' "$PC" | $G -n '/customers$' | cut -d: -f1)" ] || die "pgstart C: the table read before any request"
[ "$($G -cF '(Hibernate'"'"'s Database JDBC URL line - masked in place)' .r-pgstart.out)" = 4 ] || die "pgstart: each of the four logs held the password once, masked"
echo "  pgstart: A (before/, fresh a1) and A' (fresh a2) exit 1 - Application run failed · 'database': Invocation of init method failed · syntax error at or near \"AUTO_INCREMENT\"; B (after/, fresh b1) ready, Kavya 201, psql 1-5|Kavya, the SQL logger's insert lines 0 - TiffinBox's JDBC repository wrote her; C the restart on b1 reads 1-4, no Kavya, before any request; Hibernate's URL line masked, 4 logs"

# "H2 never minded: the seven the same on both trees, the catalogue the same"
SV=$(cat .r-seven.out); S466='466c20ed7e0d5439cb052f32ce09de1b'
[ "$(cnt "$SV" "  exit 0 · the seven responses: 7 lines · md5 $S466")" = 2 ] || die "seven: $S466 on both trees"
has "$SV" '  the seven, after/ against before/: lines that differ: 0' "seven: 0 lines differ"
for l in '  PROBE H2'"'"'s catalogue, customer.id: [IS_IDENTITY YES | IDENTITY_GENERATION BY DEFAULT | COLUMN_DEFAULT null]' '  PROBE H2'"'"'s catalogue, pause.id: [IS_IDENTITY YES | IDENTITY_GENERATION BY DEFAULT | COLUMN_DEFAULT null]'; do [ "$(cnt "$SV" "$l")" = 2 ] || die "seven: the catalogue line on both trees: $l"; done
echo "  seven: $S466 on before/ and after/, 0 lines differ; H2's catalogue IS_IDENTITY YES · BY DEFAULT for both ids on both trees"

TS=$(cat .r-tests.out)
for l in '    TEST-com.tiffinbox.web.TiffinBoxWebTest.xml: tests 14 · failures 0 · errors 0 · skipped 0' '    TEST-com.tiffinbox.web.FullStackTest.xml: tests 3 · failures 0 · errors 0 · skipped 0' '    TEST-com.tiffinbox.web.FeedTest.xml: tests 1 · failures 0 · errors 0 · skipped 0' \
    '    in all: 3 reports · tests 18 · failures 0 · errors 0 · skipped 0' "  Surefire's console summary (its Results line): tests 18 · failures 0 · errors 0 · skipped 0 · the reports' sum the same: yes" '  exit 0 · BUILD SUCCESS · offline: yes' \
    "  Hibernate in the tests' log - lines that say Initialized JPA EntityManagerFactory: 2 · Hibernate's SQL lines: 0"; do has "$TS" "$l" "tests"; done
echo "  tests: 18 (14/3/1) from the reports, the console the same; 2 EntityManagerFactories, 0 SQL lines (a guard, R.190)"

XC=$(cat .r-xcheck.out)
has "$XC" '  the same, byte for byte: yes · md5 6ca9a85044b6d4f2b346478bbd35b92a' "xcheck: the harness's DDL = Boot's"
[ "$(cnt "$XC" '    create table customer (meals_per_day integer not null, price_per_meal integer not null, id bigint generated by default as identity, meal_type varchar(10) not null, name varchar(60) not null unique, primary key (id));')" = 2 ] || die "xcheck: the one line, twice"
echo "  xcheck: Boot's script (after/'s jar, port 19854) = the harness's, byte for byte, md5 6ca9a850… (R.212)"

EXB=$(blk exercise "in bash" "in zsh"); EXZ=$(blk exercise "in zsh" "")
for b in "$EXB" "$EXZ"; do
  ER=$(printf '%s\n' "$b" | sed '/then the solution/,$d'); ES=$(printf '%s\n' "$b" | sed -n '/then the solution/,$p')
  has "$ER" '    PROBE jdbc: prepareStatement 200 | executeUpdate 200 | addBatch 0 | executeBatch 0 | executeQuery 0 | execute 0' "exercise: the README - executeBatch 0"
  has "$ES" '    PROBE jdbc: prepareStatement 6 | executeUpdate 0 | addBatch 200 | executeBatch 4 | executeQuery 5 | execute 0' "exercise: the solution - executeBatch 4"
  [ "$(printf '%s\n' "$b" | $G -c "^  the shell is now in: this unit's folder")" = 2 ] || die "exercise: the shell back in this folder"; done
[ "$(printf '%s\n' "$EXB" | $G -v '^in ')" = "$(printf '%s\n' "$EXZ" | $G -v '^in ')" ] || die "exercise: bash and zsh print the same"
EXQ="Your turn: the README saves two hundred customers and the driver never sees a batch. Change one annotation until it does."
$G -qxF -- "**Your turn:** ${EXQ#Your turn: }" exercise/README.md || die "exercise/README.md: the spoken exercise line"
[ "$(printf '%s\n' "$EXQ" | wc -w | tr -d ' ')" = 21 ] || die "exercise: the spoken line is 21 words (R.203)"
$G -qF '@GeneratedValue(strategy = GenerationType.IDENTITY)' harness/src/probe/map/ex/ExCustomer.java || die "exercise: ExCustomer ships IDENTITY"
echo "  exercise: bash and zsh alike - the README as written: IDENTITY, executeBatch 0; the solution (one line: the annotation SEQUENCE): executeBatch 4; the shell back in this folder; 21 words"

# ---- the end: the container removed, the anchor, the ports ------------------------------------------------------------------
docker rm -f "$PGN" > /dev/null 2>&1 || die "docker rm -f $PGN failed"; PGUP=""
[ -z "$(docker ps -aq --filter "name=^${PGN}\$")" ] || die "the container $PGN is still there"
echo "  the container: removed (docker ps -a --filter name=$PGN: 0 lines)"
anchornote end
for p in $PORTS; do [ "$(listeners $p)" = 0 ] || die "something listens on $p at the end"; done
echo "  ports: nothing listens on 18425, 8080, 35729 or 19850-19859 at the end; 19859 never bound"
[ -z "$unpub" ] || die "no published hash for:$unpub - check the captures, then copy the md5s above into receipts.md5 and run again"
echo "c7-unit06: every capture 3/3 and = published; every spoken number asserted; 0 raw demo tokens, 0 raw passwords; the container removed"
